import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { _electron } from 'playwright';
import { projectRoot, generated, environment, ownedDirectory, removeOwned, waitFor, localServer, replyText, completion } from '../integration/workbench-flow.test.mjs';
import { controllerServer, seed, humanInput, assertAnswerTimeline } from '../integration/governed-workflow.test.mjs';

const handwellEvidence = await ownedDirectory('evidence','governed-ui-regression-');
async function state(page) { const result = await page.evaluate(() => window.legionDesktop.getState()); assert.equal(result.ok, true, JSON.stringify(result.error)); return result.value; }
async function visible(page, selector) { await page.waitForSelector(selector); assert.equal(await page.locator(selector).isVisible(), true); }
async function detailTab(page, name) {
  if (!await page.locator('#details-drawer').isVisible()) await page.locator('#details-toggle').click();
  await page.locator('#tab-' + name).click(); await visible(page, '#detail-' + name + ':not([hidden])');
  assert.equal(await page.locator('#tab-' + name).getAttribute('aria-selected'), 'true');
}
async function contained(page, selector) {
  const box = await page.locator(selector).boundingBox(); assert.ok(box, selector + ' visible geometry');
  const viewport = await page.evaluate(() => ({ width: innerWidth, height: innerHeight }));
  assert.ok(box.x >= 0 && box.y >= 0 && box.x + box.width <= viewport.width + 1 && box.y + box.height <= viewport.height + 1, selector + ' inside actual viewport ' + JSON.stringify({box,viewport}));
}
async function windowSize(electron, page, width, height) {
  await electron.evaluate(({BrowserWindow}, size) => BrowserWindow.getAllWindows()[0].setSize(size.width,size.height), {width,height});
  await waitFor(()=>page.evaluate(()=>innerWidth), value=>value===width, 'actual native width');
  const bounds=await electron.evaluate(({BrowserWindow})=>BrowserWindow.getAllWindows()[0].getBounds()); assert.equal(bounds.width,width);assert.equal(bounds.height,height);
}
async function palette(page,name) {
  if(await page.locator('html').getAttribute('data-theme')!==name)await page.locator('#theme-toggle').click();
  assert.equal(await page.locator('html').getAttribute('data-theme'),name);
  await waitFor(()=>page.locator('.composer-box').evaluate(node=>getComputedStyle(node).backgroundColor),color=>{const values=color.match(/\d+/gu).slice(0,3).map(Number);if(name==='dark')return values.every(value=>value<60);return values.every(value=>value>200);},'actual theme paint settles');
}
async function executionScope(page, current) {
  const scope=page.locator('#interaction-scope');assert.equal(await scope.isVisible(),true);const text=await scope.innerText();
  for(const task of current.plan.tasks){assert.ok(text.includes(task.title));assert.ok(text.includes(task.roleId));for(const file of current.fileOwners.owners.filter(owner=>owner.roleId===task.roleId).map(owner=>owner.resource))assert.ok(text.includes(file+' → '+task.roleId));for(const dependency of task.dependsOn)assert.ok(text.includes(dependency));for(const check of task.checks){assert.ok(text.includes(check.checkId));assert.ok(text.includes(check.kind));assert.ok(text.includes(check.argv.join(' ')));for(const input of check.inputResources)assert.ok(text.includes(input));assert.equal(await scope.locator('details[data-key="check-'+check.checkId+'"]').evaluate(node=>node.open),true);}for(const accepted of task.accepts??[])assert.ok(text.includes(accepted));}
  assert.ok(text.includes('最多返修 '+current.plan.governance.maxRepairRounds+' 轮'));const binding=scope.locator('details[data-key="scope-binding"]');if(!await binding.evaluate(node=>node.open))await binding.locator('summary').click();assert.ok((await binding.innerText()).includes(current.plan.planDigest));await contained(page,'#interaction-submit');await contained(page,'.modal-footer');
  const scroll=await page.locator('.modal-content').evaluate(node=>({height:node.clientHeight,total:node.scrollHeight}));assert.ok(scroll.total>scroll.height,'real execution scope independently scrolls');await page.locator('.modal-content').evaluate(node=>{node.scrollTop=node.scrollHeight;});await contained(page,'#interaction-submit');
}

