// Limited real-UA contract case: facts are controlled DOM input; no SDK/host result is mocked
// into the complete workflow. This executes the production renderer region method in Chromium.
test('actual Chromium preserves focused same-ID summary when record facts change', { timeout: 25000 }, async () => {
  const location = await ownedDirectory('fixtures', 'handwell-region-focus-'); const userData = await ownedDirectory('user-data', 'handwell-region-focus-'); await fs.mkdir(handwellEvidence, {recursive:true}); let electron;
  const rendererUrl=pathToFileURL(join(projectRoot,'apps/desktop/src/interface/renderer.mjs')).href;
  await fs.writeFile(join(location,'focus.mjs'), `import {_Renderer} from ${JSON.stringify(rendererUrl)};const renderer=new _Renderer(document,{});window.updateFacts=text=>renderer.region('facts',{text},container=>{const detail=renderer.disclosure('same-evidence','Actual check');detail.append(renderer.node('p',text));container.append(detail);});window.updateFacts('current plan');`);
  await fs.writeFile(join(location,'focus.html'),'<!doctype html><html><body><div id="facts"></div><script type="module" src="focus.mjs"></script></body></html>');
  const harness=join(location,'entry.mjs'); await fs.writeFile(harness, `import {app,BrowserWindow} from 'electron';app.setPath('userData',${JSON.stringify(userData)});app.setPath('sessionData',${JSON.stringify(userData)});app.whenReady().then(async()=>{const window=new BrowserWindow({show:false,webPreferences:{nodeIntegration:false,contextIsolation:true,sandbox:true}});await window.loadFile(${JSON.stringify(join(location,'focus.html'))});});app.on('window-all-closed',()=>app.quit());`);
  try{
    electron=await _electron.launch({executablePath:join(projectRoot,'apps/desktop/node_modules/electron/dist/Electron.app/Contents/MacOS/Electron'),args:[harness],env:environment(),timeout:15000});const page=await electron.firstWindow();await page.waitForSelector('#facts summary');
    const observed=await page.evaluate(()=>{const original=document.querySelector('#facts summary');original.focus();const before=document.activeElement===original;window.updateFacts('historical plan');const replacement=document.querySelector('#facts summary');return {before,originalConnected:original.isConnected,replaced:replacement!==original,afterFocus:document.activeElement===replacement,activeTag:document.activeElement.tagName,activeText:document.activeElement.textContent};});
    await fs.writeFile(join(handwellEvidence,'actual-region-focus.json'),JSON.stringify({coverage:'Production Renderer.region + actual Chromium UA; controlled DOM facts, not host end-to-end',observed},null,2));
    assert.equal(observed.before,true);assert.equal(observed.replaced,true);assert.equal(observed.originalConnected,false);assert.equal(observed.afterFocus,true,JSON.stringify(observed));
  }finally{if(electron)await electron.close();await removeOwned(location,join(generated,'fixtures'));await removeOwned(userData,join(generated,'user-data'));}
});

