  try{const selected=await projects.select(root);assert.equal(selected.ok,true);const project=selected.value;const saved=await projects.saveProject({...project,fileOwners:new ProjectFileOwners({projectId:project.id,version:'legacy-input',owners:[{resource:'src.mjs',roleId:'LegacyBuilder'},...Array.from({length:11},(_,index)=>({resource:'legacy-'+index+'.mjs',roleId:'LegacyBuilder'+(index+2)}))]})},{expectedFileOwnersDigest:project.fileOwners.digest});assert.equal(saved.ok,true);}finally{await projects.close();}
